// Generates TrustedBrowserData.kt: the browsers whose reported web address KiteVault autofill
// trusts, each with the SHA-256 of its release signing certificate.
//
// The certificates are NOT typed in by hand. They come from Google's published list of
// privileged browsers (the same list Android's own password manager uses):
//   https://www.gstatic.com/gpm-passkeys-privileged-apps/apps.json
// Run:  node scripts/make-trusted-browsers.js
// Then review the diff of the generated file before committing it.
const fs = require('fs');
const path = require('path');

const SOURCE = 'https://www.gstatic.com/gpm-passkeys-privileged-apps/apps.json';
const OUT = path.join(
  __dirname,
  '..',
  'src/native/keystore/android/src/main/java/expo/modules/kitevaultkeystore/autofill/TrustedBrowserData.kt',
);

// Which browsers to trust. Adding one here is a deliberate security decision.
const WANTED = [
  'com.android.chrome',
  'com.chrome.beta',
  'com.chrome.dev',
  'com.chrome.canary',
  'org.mozilla.firefox',
  'org.mozilla.firefox_beta',
  'org.mozilla.fenix',
  'com.microsoft.emmx',
  'com.microsoft.emmx.beta',
  'com.microsoft.emmx.dev',
  'com.microsoft.emmx.canary',
  'com.brave.browser',
  'com.brave.browser_beta',
  'com.brave.browser_nightly',
  'com.vivaldi.browser',
  'com.sec.android.app.sbrowser',
  'com.sec.android.app.sbrowser.beta',
  'com.duckduckgo.mobile.android',
  'com.opera.browser',
  'com.opera.browser.beta',
  'app.vanadium.browser',
];

async function main() {
  const res = await fetch(SOURCE);
  if (!res.ok) throw new Error(`Download failed: HTTP ${res.status}`);
  const list = await res.json();
  const byPackage = new Map();
  for (const app of list.apps) {
    if (app.type !== 'android') continue;
    // Only release builds. "userdebug" certificates belong to development builds.
    const certs = app.info.signatures
      .filter((s) => s.build === 'release')
      .map((s) => s.cert_fingerprint_sha256.replace(/:/g, '').toUpperCase());
    if (certs.length > 0) byPackage.set(app.info.package_name, certs);
  }
  const missing = WANTED.filter((p) => !byPackage.has(p));
  if (missing.length > 0) throw new Error(`Not in the source list: ${missing.join(', ')}`);

  const rows = WANTED.map((pkg) => {
    const certs = [...new Set(byPackage.get(pkg))].map((c) => `"${c}"`).join(', ');
    return `    "${pkg}" to setOf(${certs}),`;
  }).join('\n');

  const text = `package expo.modules.kitevaultkeystore.autofill

// GENERATED by scripts/make-trusted-browsers.js. Do not edit by hand; run the script and review.
// Source: ${SOURCE}
// Generated: ${new Date().toISOString().slice(0, 10)}

/** Browsers whose reported web address we trust, with their release signing certificates (SHA-256, upper-case hex, no colons). */
internal object TrustedBrowserData {
  val certificatesByPackage: Map<String, Set<String>> = mapOf(
${rows}
  )
}
`;
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, text);
  console.log(`Wrote ${WANTED.length} browsers to ${path.relative(process.cwd(), OUT)}`);
}

main().catch((e) => {
  console.error(e.message);
  process.exit(1);
});
